gBs(){return"\u0639\u0645\u0648\u0644\u062a\u064a"},
OX(a){return A.cf(a,null,this.a,null,"\u062a\u0648\u0635\u064a\u0644\u0629 \u0648\u0627\u062d\u062f\u0629 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u062a\u0639\u064a\u064a\u0646",""+a+" \u062a\u0648\u0635\u064a\u0644\u0627\u062a \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u062a\u0639\u064a\u064a\u0646",null,"\u0644\u0627 \u062a\u0648\u062c\u062f \u062a\u0648\u0635\u064a\u0644\u0627\u062a \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u062a\u0639\u064a\u064a\u0646")},
