gTy(){return"\u0627\u0644\u0645\u0631\u0633\u0644 \u0644\u0644\u0643\u0634\u0648\u0641\u0627\u062a \u0648\u0627\u0644\u062a\u0630\u0643\u064a\u0631\u0627\u062a \u0627\u0644\u0622\u0644\u064a\u0629"},
gTu(){return"\u0631\u0642\u0645 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u062a\u062c\u0627\u0631\u064a"},
gTS(){return"\u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a"},
gTq(){return"\u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629"},
gTI(){return"\u0627\u0644\u0628\u0627\u062f\u0626\u0629"},
