gOd(){return"\u0627\u0644\u0641\u0631\u064a\u0642 \u0627\u0644\u0633\u062d\u0627\u0628\u064a \u2014 \u0639\u0631\u0636 \u0623\u0648 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0623\u0639\u0636\u0627\u0621"},
gOi(){return"\u062f\u0639\u0648\u0629 \u0645\u0648\u0638\u0641 \u0639\u0628\u0631 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a"},
Oq(a){return"\u0625\u0632\u0627\u0644\u0629 "+a+"\u061f"},
gOp(){return"\u0644\u0646 \u064a\u062a\u0645\u0643\u0646\u0648\u0627 \u0628\u0639\u062f \u0627\u0644\u0622\u0646 \u0645\u0646 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632. \u0643\u0644 \u0645\u0627 \u0623\u0646\u0634\u0623\u0648\u0647 \u0623\u0648 \u062a\u0645 \u062a\u0643\u0644\u064a\u0641\u0647\u0645 \u0628\u0647 \u2014 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0627\u0644\u062a\u0633\u0644\u064a\u0645\u0627\u062a \u0648\u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u2014 \u064a\u0628\u0642\u0649 \u0643\u0645\u0627 \u0647\u0648\u060c \u0645\u0646\u0633\u0648\u0628\u064b\u0627 \u0625\u0644\u064a\u0647\u0645 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627 \u0645\u0646 \u0647\u0646\u0627\u061b \u0627\u0637\u0644\u0628 \u0645\u0646\u0647\u0645 \u0625\u0639\u0627\u062f\u0629 \u0625\u0636\u0627\u0641\u062a\u0647\u0645 \u0643\u0639\u0636\u0648 \u0641\u0631\u064a\u0642 \u062c\u062f\u064a\u062f \u0625\u0630\u0627 \u0639\u0627\u062f\u0648\u0627."},
Os(a){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 "+a+"."},
Or(a,b){return"\u062a\u0639\u0630\u0631\u062a \u0625\u0632\u0627\u0644\u0629 "+a+": "+b},
gFw(){return"\u0625\u0632\u0627\u0644\u0629"},
gOj(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0647\u0627\u062a\u0641"},
gOw(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0633\u0631\u064a"},
gOc(){return"\u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u062f\u064a\u0631"},
gOb(){return"\u064a\u0645\u0643\u0646\u0647 \u062a\u0639\u062f\u064a\u0644 \u0648\u062d\u0630\u0641 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0627\u0644\u0645\u0634\u062a\u0631\u064a\u0627\u062a \u0648\u0627\u0644\u0633\u0646\u062f\u0627\u062a \u0627\u0644\u0645\u064f\u0631\u062d\u0651\u0644\u0629 \u2014 \u0639\u0627\u062f\u0629\u064b \u0644\u0644\u0645\u0627\u0644\u0643 \u0641\u0642\u0637."},
gOg(){return"\u062a\u0639\u062f\u064a\u0644 \u0639\u0636\u0648 \u0627\u0644\u0641\u0631\u064a\u0642"},
gOm(){return"\u0627\u0644\u0647\u0627\u062a\u0641 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gOF(){return"\u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0633\u0631\u064a \u0627\u0644\u0623\u0648\u0644\u064a (4 \u0623\u0631\u0642\u0627\u0645 \u0623\u0648 \u0623\u0643\u062b\u0631)"},
gOE(){return"\u0633\u064a\u0633\u062a\u062e\u062f\u0645\u0648\u0646\u0647 \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u2014 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0646\u0634\u0627\u0624\u0647\u0645 \u0628\u062f\u0648\u0646\u0647."},
gOz(){return"\u0627\u0644\u062f\u0648\u0631"},
gOD(){return"\u0641\u0631\u064a\u0642 \u0627\u0644\u0645\u0628\u064a\u0639\u0627\u062a"},
gRS(){return"\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u062d\u0633\u0627\u0628"},
gHi(){return"\u0627\u0633\u0645 \u0627\u0644\u0628\u0646\u0643 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gHg(){return"\u0631\u0642\u0645 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gHk(){return"\u0622\u064a\u0628\u0627\u0646 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gRT(){return'\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0645\u062b\u0644 "ADCB \u0627\u0644\u062c\u0627\u0631\u064a")'},
gS3(){return"\u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a"},
ga1_(){return'\u0645\u062b\u0644 "\u0639\u0647\u062f\u0629 \u0645\u0643\u062a\u0628 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644"'},
ga0X(){return"\u0627\u0644\u0648\u0635\u064a (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
ga15(){return"\u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a"},
gKF(){return"\u0627\u0644\u0645\u0628\u0644\u063a"},
ga0U(){return"\u0627\u0644\u0641\u0626\u0629"},
ga14(){return"\u0645\u0644\u0627\u062d\u0638\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gVV(){return"\u0627\u0643\u062a\u0628 RESET \u0644\u0644\u062a\u0623\u0643\u064a\u062f"},
gVO(){return"\u0645\u0633\u062d \u0643\u0644 \u0634\u064a\u0621"},
VU(a){return"\u0641\u0634\u0644\u062a \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0639\u064a\u064a\u0646: "+a},
gVS(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u061f"},
gVP(){return"\u064a\u0624\u062f\u064a \u0647\u0630\u0627 \u0625\u0644\u0649 \u0645\u062d\u0648 \u0643\u0644 \u0634\u064a\u0621 \u0623\u062f\u062e\u0644\u0647 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u062a\u062c\u0627\u0631\u064a \u0623\u0648 \u0627\u0633\u062a\u0648\u0631\u062f\u0647 \u062d\u0631\u0641\u064a\u064b\u0627: \u0643\u0644 \u0639\u0645\u064a\u0644 \u0648\u0645\u0648\u0631\u062f \u0648\u0635\u0646\u0641 \u0648\u0641\u0627\u062a\u0648\u0631\u0629 \u0648\u0634\u0631\u0627\u0621 \u0648\u0625\u0634\u0639\u0627\u0631 \u0648\u0634\u064a\u0643 \u0648\u062a\u0633\u0644\u064a\u0645 \u0648\u0633\u0646\u062f \u0648\u0642\u064a\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630 \u0648\u062d\u0631\u0643\u0629 \u0645\u062e\u0632\u0648\u0646 \u0648\u062d\u0633\u0627\u0628 \u0628\u0646\u0643\u064a \u0648\u0645\u0648\u0638\u0641 \u0648\u0633\u062c\u0644 \u0627\u0644\u062a\u062f\u0642\u064a\u0642.\n\n\u0641\u0642\u0637 \u0627\u0644\u0641\u0631\u0639 (\u0627\u0644\u0641\u0631\u0648\u0639) \u0648\u0645\u0644\u0641 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u062a\u0633\u062c\u064a\u0644\u0627\u062a \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u062a\u0646\u062c\u0648 \u2014 \u062d\u062a\u0649 \u062a\u062a\u0645\u0643\u0646 \u0645\u0646 \u0627\u0644\u062f\u062e\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0643\u0644 \u0634\u064a\u0621 \u0622\u062e\u0631 \u064a\u0639\u0648\u062f \u0641\u0627\u0631\u063a\u064b\u0627\u060c \u062a\u0645\u0627\u0645\u064b\u0627 \u0645\u062b\u0644 \u0634\u0631\u0643\u0629 \u062c\u062f\u064a\u062f\u0629 \u062a\u0645\u0627\u0645\u064b\u0627.\n\n\u0627\u0633\u062a\u062e\u062f\u0645 \u0647\u0630\u0627 \u0644\u0645\u0633\u062d \u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0645\u0643\u0631\u0631 \u0623\u0648 \u0641\u0627\u0633\u062f \u0642\u0628\u0644 \u062a\u0634\u063a\u064a\u0644\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627."},
